INSERT INTO phanhoi (maph, makh, manv, masp, noidung, danhgia, phanhoilai, trangthai, ngaygui, ngayxuly) VALUES (1, 18, 1, 3, 'Không gian yên tĩnh, cà phê sữa đá chuẩn vị. Rất hài lòng.', 5, 'Cảm ơn bạn đã góp ý. Quán đã ghi nhận và sẽ cải thiện trong thời gian tới.', 'Đã xử lý', '2026-09-25 19:25:00', '2026-10-12 15:00:00');
INSERT INTO phanhoi (maph, makh, manv, masp, noidung, danhgia, phanhoilai, trangthai, ngaygui, ngayxuly) VALUES (2, 19, 4, 30, 'Nhân viên dễ thương nhưng quán hơi ồn.', 3, 'Quán rất tiếc vì trải nghiệm chưa tốt. Vui lòng liên hệ hotline để được hỗ trợ thêm.', 'Đã xử lý', '2026-10-10 20:28:00', '2026-10-12 15:00:00');
